import { apiFetch } from '../lib/api.js'

export interface NoteSummary {
  id: string
  path: string
  type: string
  name: string
  frontmatter: Record<string, unknown>
  updatedAt: string
}

export type VaultTree = Record<string, NoteSummary[]>

export function getVaultTree(vaultId: string): Promise<VaultTree> {
  return apiFetch(`/vaults/${vaultId}/tree`)
}

export interface NoteDetail {
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function getNote(vaultId: string, path: string): Promise<NoteDetail> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`)
}

export interface UpdateNoteInput {
  frontmatter?: Record<string, unknown>
  body?: string
}

export interface UpdateNoteResult {
  id: string
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function updateNote(vaultId: string, path: string, input: UpdateNoteInput): Promise<UpdateNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`, { method: 'PUT', body: JSON.stringify(input) })
}

export interface CreateNoteInput {
  type: string
  name: string
}

export interface CreateNoteResult {
  id: string
  path: string
  type: string
  name: string
}

export function createNote(vaultId: string, input: CreateNoteInput): Promise<CreateNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes`, { method: 'POST', body: JSON.stringify(input) })
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { mockJsonResponse } from '../lib/api'
import { createNote, getNote, getVaultTree, updateNote } from './notes'

describe('notes api', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('getVaultTree calls GET /api/vaults/:id/tree', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      mockJsonResponse(200, {
        people: [
          { id: 'n1', path: 'people/jane', type: 'people', name: 'jane', frontmatter: {}, updatedAt: '2026-01-01' },
        ],
      }),
    )
    vi.stubGlobal('fetch', fetchMock)

    const tree = await getVaultTree('v1')

    expect(tree.people).toHaveLength(1)
    expect(fetchMock).toHaveBeenCalledWith('/api/vaults/v1/tree', expect.objectContaining({ credentials: 'include' }))
  })

  it('getNote calls GET /api/vaults/:id/notes/:path', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      mockJsonResponse(200, {
        path: 'people/jane',
        frontmatter: { type: 'people' },
        body: '# Jane\n\nNotes here.',
        updatedAt: '2026-01-01',
      }),
    )
    vi.stubGlobal('fetch', fetchMock)

    const note = await getNote('v1', 'people/jane')

    expect(note.body).toBe('# Jane\n\nNotes here.')
    expect(fetchMock).toHaveBeenCalledWith(
      '/api/vaults/v1/notes/people/jane',
      expect.objectContaining({ credentials: 'include' }),
    )
  })

  it('updateNote calls PUT /api/vaults/:id/notes/:path with the body', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      mockJsonResponse(200, {
        id: 'n1',
        path: 'people/jane',
        frontmatter: { type: 'people' },
        body: 'Updated body.',
        updatedAt: '2026-01-02',
      }),
    )
    vi.stubGlobal('fetch', fetchMock)

    const result = await updateNote('v1', 'people/jane', { body: 'Updated body.' })

    expect(result.body).toBe('Updated body.')
    expect(fetchMock).toHaveBeenCalledWith(
      '/api/vaults/v1/notes/people/jane',
      expect.objectContaining({ method: 'PUT', body: JSON.stringify({ body: 'Updated body.' }) }),
    )
  })

  it('createNote POSTs /api/vaults/:id/notes with type and name', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      mockJsonResponse(201, { id: 'n1', path: 'people/jane', type: 'people', name: 'jane', frontmatter: {}, body: '', updatedAt: '2026-01-01' }),
    )
    vi.stubGlobal('fetch', fetchMock)

    const result = await createNote('v1', { type: 'people', name: 'jane' })

    expect(result.path).toBe('people/jane')
    expect(fetchMock).toHaveBeenCalledWith(
      '/api/vaults/v1/notes',
      expect.objectContaining({ method: 'POST', body: JSON.stringify({ type: 'people', name: 'jane' }) }),
    )
  })
})

